-- 总账科目设置取数：在 FH100 上执行（只读）。结果按之前的格式（分号分隔、首行字段名）给我。
-- 列清单取自测试库 TEST20261012 的 OACP / OITB / OWHS 中所有科目类字段；报“列不存在”就删掉那列。

-- G1 → 11_过账期间科目确定.txt（OACP，2026 年度）
SELECT "PeriodCat", "LinkAct_1", "LinkAct_2", "LinkAct_3", "LinkAct_4", "LinkAct_5", "LinkAct_6", "ComissAct", "LinkAct_8", "LinkAct_9", "LinkAct_10", "LinkAct_11", "LinkAct_12", "LinkAct_13", "LinkAct_14", "LinkAct_15", "LinkAct_16", "LinkAct_17", "LinkAct_18", "DfltIncom", "ExmptIncom", "DfltExpn", "ForgnIncm", "ECIncome", "ForgnExpn", "DfltRateDi", "DecresGlAc", "LinkAct_27", "DftStockOB", "LinkAct_19", "LinkAct_20", "LinkAct_21", "LinkAct_22", "LinkAct_23", "LinkAct_24", "LinkAct_25", "LinkAct_26", "IncresGlAc", "RturnngAct", "COGM_Act", "AlocCstAct", "VariancAct", "PricDifAct", "CDownPymnt", "VDownPymnt", "CBoERcvble", "CBoEOnClct", "CBoEPresnt", "CBoEDiscnt", "CUnpaidBoE", "VBoEPayble", "VAsstBoEPy", "COpenDebts", "VOpenDebts", "PurchseAct", "PaReturnAc", "PaOffsetAc", "LinkAct_28", "ExDiffAct", "BalanceAct", "BnkChgAct", "LinkAct_29", "LinkAct_30", "IncmAcct", "ExpnAcct", "VatRevAct", "ExpClrAct", "ExpOfstAct", "CostRevAct", "RepomoAct", "WipVarAcct", "SaleVatOff", "PurcVatOff", "DpmSalAct", "DpmPurAct", "ExpVarAct", "CostOffAct", "ECExepnses", "StockAct", "DflInPrcss", "DfltInCstm", "DfltProfit", "DfltLoss", "VAssets", "StockRvAct", "StkRvOfAct", "WipAcct", "DfltCard", "ShpdGdsAct", "GlRvOffAct", "OverpayAP", "UndrpayAP", "OverpayAR", "UndrpayAR", "ARCMAct", "ARCMExpAct", "ARCMFrnAct", "ARCMEUAct", "APCMAct", "APCMFrnAct", "APCMEUAct", "NegStckAct", "StkInTnAct", "GLGainXdif", "GLLossXdif", "AmountDiff", "SlfInvIncm", "SlfInvExpn", "OnHoldAct", "PlaAct", "ICClrAct", "OCClrAct", "PurBalAct", "WhICenAct", "WhOCenAct", "SalDpmInt", "PurDpmInt", "ExrateOnDt", "EURecvAct", "EUPayAct", "WipOffset", "StockOffst", "DunIntrst", "DunFee", "TDSInterst", "TDSCharges", "SrvTaxClr", "ARConDiffG", "ARConDiffL", "APConDiffG", "APConDiffL", "GLConDiffG", "GLConDiffL", "FreeChrgSA", "FreeChrgPU", "TDSFee", "ResRevenue", "ResExpense", "ResSalesCr", "ResPurchCr", "ResNotInv", "ResStdExp1", "ResStdExp2", "ResStdExp3", "ResStdExp4", "ResStdExp5", "ResStdExp6", "ResStdExp7", "ResStdExp8", "ResStdExp9", "ResStdEx10", "ResWipAct", "ResScrapAc", "WipOffPlAc", "ResOffPlAc", "ERDInARAct", "ERDInAPAct", "CSDInARAct", "CSDInAPAct", "GSTInAct", "GSTInterst", "GSTCharges", "GSTFee", "WTInARAct", "WTInAPAct", "WTExDifAct"
  FROM OACP WHERE "PeriodCat" = '2026';

-- G2 → 12_物料组科目.txt（OITB，样本物料用到的 101–104）
SELECT "ItmsGrpCod", "ItmsGrpNam", "BalInvntAc", "SaleCostAc", "TransferAc", "RevenuesAc", "VarianceAc", "DecreasAc", "IncreasAc", "ReturnAc", "ExpensesAc", "EURevenuAc", "EUExpensAc", "FrRevenuAc", "FrExpensAc", "ExmptIncom", "PriceDifAc", "ExchangeAc", "BalanceAcc", "PurchaseAc", "PAReturnAc", "PurchOfsAc", "ShpdGdsAct", "VatRevAct", "DecresGlAc", "IncresGlAc", "StokRvlAct", "StkOffsAct", "WipAcct", "WipVarAcct", "CostRvlAct", "CstOffsAct", "ExpClrAct", "ExpOfstAct", "ARCMAct", "ARCMFrnAct", "ARCMEUAct", "ARCMExpAct", "APCMAct", "APCMFrnAct", "APCMEUAct", "RevRetAct", "NegStckAct", "StkInTnAct", "PurBalAct", "WhICenAct", "WhOCenAct", "WipOffset", "StockOffst", "FreeChrgSA", "FreeChrgPU"
  FROM OITB WHERE "ItmsGrpCod" IN (101, 102, 103, 104) ORDER BY "ItmsGrpCod";

-- G3 → 13_仓库科目.txt（OWHS，样本用到的仓库；物料按物料组取科目时一般用不到，留作核对）
SELECT "WhsCode", "BalInvntAc", "SaleCostAc", "TransferAc", "RevenuesAc", "VarianceAc", "DecreasAc", "IncreasAc", "ReturnAc", "ExpensesAc", "EURevenuAc", "EUExpensAc", "FrRevenuAc", "FrExpensAc", "ExmptIncom", "PriceDifAc", "ExchangeAc", "BalanceAcc", "PurchaseAc", "PAReturnAc", "PurchOfsAc", "ShpdGdsAct", "VatRevAct", "DecresGlAc", "IncresGlAc", "StokRvlAct", "StkOffsAct", "WipAcct", "WipVarAcct", "CostRvlAct", "CstOffsAct", "ExpClrAct", "ExpOfstAct", "ARCMAct", "ARCMFrnAct", "ARCMEUAct", "ARCMExpAct", "APCMAct", "APCMFrnAct", "APCMEUAct", "RevRetAct", "NegStckAct", "StkInTnAct", "PurBalAct", "WhICenAct", "WhOCenAct", "WipOffset", "StockOffst", "Shipper", "FreeChrgSA", "FreeChrgPU"
  FROM OWHS WHERE "WhsCode" IN ('S001','S002','S004','S011','S100','S101','S102','S106','S202') ORDER BY "WhsCode";

-- G4 → 14_高级总账科目规则.txt（OGAR，2026 年度）
--   FH100 物料组 / 仓库上的科目都是空的，库存类科目来自高级总账科目确定规则；
--   成本代码（0501、0801）也直接按物料组读 OGAR."StockAct"。
SELECT * FROM OGAR WHERE "PeriodCat" = '2026' ORDER BY "AbsEntry";
